#include "EpaperDisplay.h"

#include <SPI.h>
#include <GxEPD2_BW.h>

#include "ActivityIcons.h"
#include "IconOverview.h"
#include "PolylineReader.h"
// ASCII + Latin-1 (ä, ö, ü, ß, é, ...), generated by tools/fonts/make_fonts.sh
#include "fonts/FreeSans12pt8b.h"
#include "fonts/FreeSans18pt8b.h"
#include "fonts/FreeSansBold24pt8b.h"

#define VERSION "v0.0.1"

#define HEADING_START_X 20
#define HEADING_START_Y 40

#define HEADING_ICON_SIZE 40
#define HEADING_ICON_GAP 12

// Icons centered on the cap height of the heading font (~25 px)
#define HEADING_ICON_Y (HEADING_START_Y - 12 - HEADING_ICON_SIZE / 2)

#define BODY_START_X 40
#define BODY_START_Y 100

#define FOOTER_SIZE_Y 20

#define MAP_MARGIN 20
#define MAP_LINE_WIDTH 3

// CS=15, DC=27, RST=26, BUSY=25
static GxEPD2_BW<GxEPD2_750_T7, GxEPD2_750_T7::HEIGHT> display(GxEPD2_750_T7(15, 27, 26, 25));

// Converts UTF-8 (as Strava sends it) to Latin-1, the encoding of the fonts above.
// Typographic quotes and dashes become ASCII; other characters (emoji, ...) are dropped.
static String utf8ToLatin1(const char *utf8) {
    String out;
    const uint8_t *s = (const uint8_t *)utf8;
    while (*s) {
        uint32_t cp;
        uint8_t extra;
        if (*s < 0x80) {
            cp = *s;
            extra = 0;
        } else if ((*s & 0xE0) == 0xC0) {
            cp = *s & 0x1F;
            extra = 1;
        } else if ((*s & 0xF0) == 0xE0) {
            cp = *s & 0x0F;
            extra = 2;
        } else if ((*s & 0xF8) == 0xF0) {
            cp = *s & 0x07;
            extra = 3;
        } else {  // invalid lead byte
            s++;
            continue;
        }
        s++;
        for (; extra > 0 && (*s & 0xC0) == 0x80; extra--, s++) cp = (cp << 6) | (*s & 0x3F);
        if (extra > 0) continue;  // truncated sequence

        if (cp < 0x80 || (cp >= 0xA0 && cp <= 0xFF)) {
            out += (char)cp;
        } else if (cp == 0x2018 || cp == 0x2019 || cp == 0x201A) {
            out += '\'';
        } else if (cp == 0x201C || cp == 0x201D || cp == 0x201E) {
            out += '"';
        } else if (cp == 0x2013 || cp == 0x2014) {
            out += '-';
        } else if (cp == 0x2026) {
            out += "...";
        }
    }
    return out;
}

static void printText(const char *utf8) {
    display.print(utf8ToLatin1(utf8));
}

// Only draws into the buffer; call inside a firstPage()/nextPage() loop and never
// change the window here, that would clip everything drawn in the same loop.
static void drawHeading(const char *heading, Icon icon = Icon::None) {
    drawIcon(display, icon, HEADING_START_X, HEADING_ICON_Y, HEADING_ICON_SIZE, GxEPD_BLACK,
             GxEPD_WHITE);

    display.setFont(&FreeSans18pt8b);
    display.setCursor(HEADING_START_X + HEADING_ICON_SIZE + HEADING_ICON_GAP, HEADING_START_Y);
    printText(heading);
    const int16_t lineY = HEADING_START_Y + 20;
    display.drawLine(HEADING_START_X, lineY, display.width() - HEADING_START_X, lineY, GxEPD_BLACK);
}

void initDisplay() {
    SPI.end();
    SPI.begin(13, 12, 14, 15);  // SCK=13, MISO=12 (unused), MOSI=14, SS=15
    display.init(115200, true, 2, false);
    display.setRotation(0);
}

// Achievement badge at the right end of the heading, with the count left of it.
// Only draws into the buffer, like drawHeading().
static void drawAchievements(uint8_t achievements) {
    if (achievements == 0) return;

    const int16_t iconX = display.width() - HEADING_START_X - HEADING_ICON_SIZE;
    drawIcon(display, Icon::Achievement, iconX, HEADING_ICON_Y, HEADING_ICON_SIZE, GxEPD_BLACK,
             GxEPD_WHITE);

    // you can probably only get max. 99 achievements
    char text[8];
    snprintf(text, sizeof(text), "%02ux", achievements < 99 ? achievements : 99);

    // right-align the text in front of the icon
    display.setFont(&FreeSans18pt8b);
    int16_t x1, y1;
    uint16_t w, h;
    display.getTextBounds(text, 0, HEADING_START_Y, &x1, &y1, &w, &h);
    display.setCursor(iconX - HEADING_ICON_GAP - w - x1, HEADING_START_Y);
    display.print(text);
}

static void drawActivityStats(StravaActivity act) {
    char distance[16];
    snprintf(distance, sizeof(distance), "%.2f km", act.distance_km);

    display.setFont(&FreeSans12pt8b);
    display.setCursor(BODY_START_X, BODY_START_Y);
    printText(act.date.c_str());

    display.setFont(&FreeSansBold24pt8b);
    display.setCursor(BODY_START_X, 380);
    display.print(distance);
}

// Draws the route, fitted into the right half of the screen below the heading.
// Only draws into the buffer, like drawHeading().
static void drawActivityMap(const String &polyline) {
    // Bounding box of the route, in 1e-5 degrees
    int32_t lat, lng;
    int32_t minLat = INT32_MAX, maxLat = INT32_MIN, minLng = INT32_MAX, maxLng = INT32_MIN;
    PolylineReader bounds(polyline.c_str());
    while (bounds.next(lat, lng)) {
        minLat = min(minLat, lat);
        maxLat = max(maxLat, lat);
        minLng = min(minLng, lng);
        maxLng = max(maxLng, lng);
    }
    if (minLat > maxLat) return;  // no points

    // A degree of longitude gets shorter towards the poles
    const float midLatRad = (minLat + maxLat) / 2 * 1e-5f * DEG_TO_RAD;
    const float lngFactor = cosf(midLatRad);
    const float routeW = (maxLng - minLng) * lngFactor;
    const float routeH = maxLat - minLat;

    const int16_t boxX = display.width() / 2 + MAP_MARGIN;
    const int16_t boxY = HEADING_START_Y + 20 + MAP_MARGIN;  // below the heading line
    const int16_t boxW = display.width() - HEADING_START_X - boxX;
    const int16_t boxH = display.height() - MAP_MARGIN - boxY;

    // Same scale on both axes, so the route isn't distorted; centered in the box
    const float scale =
        min(routeW > 0 ? boxW / routeW : INFINITY, routeH > 0 ? boxH / routeH : INFINITY);
    const float s = isinf(scale) ? 0 : scale;  // a single point: draw it in the center
    const float offsetX = boxX + (boxW - routeW * s) / 2;
    const float offsetY = boxY + (boxH - routeH * s) / 2;

    PolylineReader route(polyline.c_str());
    int16_t prevX = 0, prevY = 0;
    bool first = true;
    while (route.next(lat, lng)) {
        const int16_t x = offsetX + (lng - minLng) * lngFactor * s;
        const int16_t y = offsetY + (maxLat - lat) * s;  // north is up
        if (first) {
            display.fillCircle(x, y, MAP_LINE_WIDTH, GxEPD_BLACK);  // start point
            first = false;
        } else {
            // Thick line: the same line shifted by up to ±1 px in both directions
            for (int8_t d = -(MAP_LINE_WIDTH / 2); d <= MAP_LINE_WIDTH / 2; d++) {
                display.drawLine(prevX + d, prevY, x + d, y, GxEPD_BLACK);
                display.drawLine(prevX, prevY + d, x, y + d, GxEPD_BLACK);
            }
        }
        prevX = x;
        prevY = y;
    }
}

static void drawFooter() {
    display.setFont(&FreeSans12pt8b);
    const int16_t y = display.height() - (FOOTER_SIZE_Y / 2);

    // center the text horizontally, whatever its length
    int16_t x1, y1;
    uint16_t w, h;
    display.getTextBounds(VERSION, 0, y, &x1, &y1, &w, &h);
    display.setCursor((display.width() - w) / 2 - x1, y);
    printText(VERSION);
}

void drawActivity(StravaActivity act) {
    display.setFullWindow();
    display.firstPage();
    do {
        display.fillScreen(GxEPD_WHITE);
        display.setTextColor(GxEPD_BLACK);

        drawHeading(act.name.c_str(), iconForSportType(act.type.c_str()));
        drawAchievements(act.achievement_count);

        drawActivityStats(act);

        if (act.showMap) {
            display.drawLine(display.width() / 2, BODY_START_Y, display.width() / 2,
                             display.height() - (FOOTER_SIZE_Y * 2), GxEPD_BLACK);

            drawActivityMap(act.map);
        }

        drawFooter();

    } while (display.nextPage());
}

void drawError(const char *message) {
    display.setFullWindow();
    display.firstPage();
    do {
        display.fillScreen(GxEPD_WHITE);
        display.setTextColor(GxEPD_BLACK);
        drawHeading("Error:", Icon::Error);
        display.setCursor(BODY_START_X, BODY_START_Y);
        printText(message);
    } while (display.nextPage());
}

void drawIconOverviewScreen() {
    display.setFullWindow();
    display.firstPage();
    do {
        drawIconOverview(display, GxEPD_BLACK, GxEPD_WHITE);
    } while (display.nextPage());
}

void hibernateDisplay() {
    display.hibernate();
}
